/*
 * prog27_soundex – reconstructed original program
 *
 * The original binary implements a classic Soundex encoder.
 * It reads the first command‑line argument, computes its
 * Soundex code and prints it with a trailing newline.
 * If no argument is supplied, or the argument is an empty
 * string, the program prints the literal string "EMPTY".
 *
 * The implementation below reproduces the observable
 * behaviour (stdout) of the original binary while using a
 * straightforward, readable C implementation.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

/*--------------------------------------------------------------
 * soundex_digit
 *
 * Returns the Soundex digit for a given alphabetic character.
 * The mapping follows the standard Soundex rules:
 *
 *   B, F, P, V           -> 1
 *   C, G, J, K, Q, S, X, Z -> 2
 *   D, T                 -> 3
 *   L                    -> 4
 *   M, N                 -> 5
 *   R                    -> 6
 *   all other characters -> 0
 *
 * The function works with both upper‑ and lower‑case input.
 *--------------------------------------------------------------*/
static int soundex_digit(char c)
{
    switch (toupper((unsigned char)c)) {
        case 'B': case 'F': case 'P': case 'V': return 1;
        case 'C': case 'G': case 'J': case 'K':
        case 'Q': case 'S': case 'X': case 'Z': return 2;
        case 'D': case 'T': return 3;
        case 'L': return 4;
        case 'M': case 'N': return 5;
        case 'R': return 6;
        default:  return 0;
    }
}

/*--------------------------------------------------------------
 * soundex_encode
 *
 * Encodes the supplied string into a 4‑character Soundex code.
 * The result is stored in a static buffer that is valid until the
 * next call.  The format is:
 *
 *   <first letter (upper case)><digit><digit><digit>
 *
 * Digits are derived from the remaining letters using soundex_digit().
 * Consecutive duplicate digits are collapsed, and any zeros are
 * omitted.  The result is padded with '0' characters if fewer than
 * three digits are produced.
 *
 * If the input string is empty, the function returns NULL.
 *--------------------------------------------------------------*/
static const char *soundex_encode(const char *s)
{
    static char out[5];          /* 4 characters + terminating NUL */
    size_t i, out_len = 0;
    int prev_digit = 0, digit;

    if (s == NULL || *s == '\0')
        return NULL;             /* signal “EMPTY" to the caller */

    out[0] = toupper((unsigned char)s[0]);   /* first letter */
    out_len = 1;
    prev_digit = soundex_digit(s[0]);        /* digit of first letter (used for duplicate suppression) */

    for (i = 1; s[i] != '\0' && out_len < 4; ++i) {
        digit = soundex_digit(s[i]);
        if (digit == 0)
            continue;               /* ignore vowels and other non‑mapped chars */
        if (digit == prev_digit)
            continue;               /* collapse consecutive duplicates */
        out[out_len++] = (char)('0' + digit);
        prev_digit = digit;
    }

    while (out_len < 4)
        out[out_len++] = '0';

    out[4] = '\0';
    return out;
}

/*--------------------------------------------------------------
 * main
 *
 * Prints the Soundex code for the first command‑line argument,
 * or the literal string "EMPTY" when no argument is supplied or
 * the argument is an empty string.
 *--------------------------------------------------------------*/
int main(int argc, char *argv[])
{
    const char *result;

    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    result = soundex_encode(argv[1]);
    if (result == NULL) {
        puts("EMPTY");
    } else {
        puts(result);
    }
    return 0;
}
